def normalize_rows(matrix, k=0.0):
    if not matrix or not matrix[0]:
        raise ValueError("empty matrix")
    cols = len(matrix[0])
    if any(len(row) != cols for row in matrix):
        raise ValueError("ragged matrix")
    out = []
    for row in matrix:
        shifted = [x + k for x in row]
        total = sum(shifted)
        if total <= 0:
            raise ValueError("non-positive row sum")
        out.append([v / total for v in shifted])
    return out

def matmul(A, B):
    if not A or not A[0] or not B or not B[0]:
        raise ValueError("empty matrix")
    n, k1 = len(A), len(A[0])
    k2, m = len(B), len(B[0])
    if any(len(r) != k1 for r in A) or any(len(r) != m for r in B):
        raise ValueError("ragged matrix")
    if k1 != k2:
        raise ValueError(f"shape mismatch: ({n},{k1}) @ ({k2},{m})")
    return [
        [sum(A[i][t] * B[t][j] for t in range(k1)) for j in range(m)]
        for i in range(n)
    ]
